/**
 * Guide tab data: GET /api/guide/features serves docs/features.json (generated by
 * scripts/build_features_json.py, validated by `make docs-check`). Read per request so a
 * regenerated file shows without a restart; a missing or malformed file is refused, never faked.
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { FastifyInstance } from "fastify";
import { ROOT } from "../config.js";

const REQUIRED = ["id", "area", "name", "summary", "stories", "stack", "alternatives", "examples", "diagram", "coverage_ids"] as const;

export type LoadResult = { ok: true; features: any[] } | { ok: false; error: string };

export function loadFeatures(path = join(ROOT, "docs", "features.json")): LoadResult {
  if (!existsSync(path)) return { ok: false, error: "docs/features.json does not exist (run python3 scripts/build_features_json.py)" };
  let data: unknown;
  try {
    data = JSON.parse(readFileSync(path, "utf8"));
  } catch (e) {
    return { ok: false, error: `docs/features.json could not be parsed (${(e as Error).message})` };
  }
  if (!Array.isArray(data) || !data.length) return { ok: false, error: "docs/features.json must be a non-empty array" };
  for (const f of data) {
    const missing = REQUIRED.filter((k) => !(k in (f ?? {})));
    if (missing.length) return { ok: false, error: `feature ${(f as any)?.id ?? "?"} is missing ${missing.join(", ")}` };
  }
  return { ok: true, features: data };
}

export function registerGuideRoutes(app: FastifyInstance, path?: string) {
  app.get("/api/guide/features", async (_req, reply) => {
    const r = loadFeatures(path);
    if (!r.ok) return reply.code(503).send({ ok: false, error: r.error, service: "bff", endpoint: "GET /api/guide/features", fix: "make docs-check" });
    return { ok: true, count: r.features.length, features: r.features, provenance: { service: "bff", endpoint: "GET /api/guide/features", source: "docs/features.json", timestamp: new Date().toISOString() } };
  });
}
